INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_CEL_BALOR_CATHMA','ENT_CEL_BALOR','SRC_CATH_MAIGE_TUIRED','Cath Maige Tuired (The Second Battle of Mag Tuired)','Cath Maige Tuired (The Second Battle of Mag Tuired)','The Tuatha De then made an alliance with the Fomoire, and Balor the grandson of Net gave his daughter Ethne to Cian the son of Dian Cecht. And she bore the glorious child, Lug. The Tuatha De came with a great fleet to Ireland to take it by force from the Fir Bolg. Upon reaching the territory of Corcu Belgatan (which is Conmaicne Mara today), they at once burned their boats so that they would not think of fleeing to them.','Whitley Stokes',1891,'https://celt.ucc.ie/published/T300010.html',NULL,'primary-verbatim',NULL,true,'Located by name; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CEL_CREDNE_CATHMA','ENT_CEL_CREDNE','SRC_CATH_MAIGE_TUIRED','Cath Maige Tuired (The Second Battle of Mag Tuired)','Cath Maige Tuired (The Second Battle of Mag Tuired)','So with Credne the brazier helping him, Dian Cecht the physician put on him a silver hand that moved as well as any other hand. p.27 Now the Tuatha De Danann lost many men in the battle, including Edleo mac Allai, and Ernmas, and Fiacha, and Tuirill Bicreo. Then those of the Fir Bolg who escaped from the battle fled to the Fomoire, and they settled in Arran and in Islay and in Man and in Rathlin.','Whitley Stokes',1891,'https://celt.ucc.ie/published/T300010.html',NULL,'primary-verbatim',NULL,true,'Located by name; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CEL_ELATHA_CATHMA','ENT_CEL_ELATHA','SRC_CATH_MAIGE_TUIRED','Cath Maige Tuired (The Second Battle of Mag Tuired)','Cath Maige Tuired (The Second Battle of Mag Tuired)','They said that it would be appropriate for them to give the kingship to Bres the son of Elatha, to their own adopted son, and that giving him the kingship would knit the Fomorians'' alliance with them, since his father Elatha mac Delbaith was king of the Fomoire. Now the conception of Bres came about in this way.','Whitley Stokes',1891,'https://celt.ucc.ie/published/T300010.html',NULL,'primary-verbatim',NULL,true,'Located by name; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CEL_INDECH_CATHMA','ENT_CEL_INDECH','SRC_CATH_MAIGE_TUIRED','Cath Maige Tuired (The Second Battle of Mag Tuired)','Cath Maige Tuired (The Second Battle of Mag Tuired)','The Fomoire had a warrior named Ochtriallach, the son of the Fomorian king Indech mac De Domnann. He suggested that every single man they had should bring a stone from the stones of the river Drowes to cast into the well Slaine in Achad Abla to the west of Mag Tuired, to the east of Lough Arrow. They went, and every man put a stone into the well. For that reason the cairn is called Ochtriallach''s Cairn.','Whitley Stokes',1891,'https://celt.ucc.ie/published/T300010.html',NULL,'primary-verbatim',NULL,true,'Located by name; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CEL_LUCHTA_CATHMA','ENT_CEL_LUCHTA','SRC_CATH_MAIGE_TUIRED','Cath Maige Tuired (The Second Battle of Mag Tuired)','Cath Maige Tuired (The Second Battle of Mag Tuired)','We have a builder already, Luchta mac Luachada.'' He said, ‘Question me, doorkeeper: I am a smith.'' The doorkeeper answered him, ‘We have a smith already, Colum Cualeinech of the three new techniques.'' He said, ‘Question me: I am a champion.'' The doorkeeper answered, ‘We do not need you. We have a champion already, Ogma mac Ethlend.'' He said again, ‘Question me.'' ‘I am a harper,'' he said. ‘We do not need you.','Whitley Stokes',1891,'https://celt.ucc.ie/published/T300010.html',NULL,'primary-verbatim',NULL,true,'Located by name; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CEL_MACHA_CATHMA','ENT_CEL_MACHA','SRC_CATH_MAIGE_TUIRED','Cath Maige Tuired (The Second Battle of Mag Tuired)','Cath Maige Tuired (The Second Battle of Mag Tuired)','p.61 Then Nuadu Silverhand and Macha the daughter of Ernmas fell at the hands of Balor grandson of Net. Casmael fell at the hands of Ochtriallach son of Indech. Lug and Balor of the piercing eye met in the battle. The latter had a destructive eye which was never opened except on a battlefield. Four men would raise the lid of the eye by a polished ring in its lid.','Whitley Stokes',1891,'https://celt.ucc.ie/published/T300010.html',NULL,'primary-verbatim',NULL,true,'Located by name; verify section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
